  '  if (!b) {\n'
  '    g.unsup(std::string("simfoto: no body ") + name);\n'
  '    return;\n'
  '  }\n'
  '  uint32_t args[12] = {};\n'
  '  int n = 0;\n'
  '  for (uint32_t v : a) args[n++] = v;\n'
  '  b(g, ctx, args, n);\n'
  '}\n'
  '\n'
  'void b_draw_window_golfer(Gfx &g, Ctx &ctx, const uint32_t *a, int) {\n'
  '  g.ensure_root(ctx);\n'
  '  const int32_t sel = ctx.gs().f_w_4c2e00[2];\n'
  '  if (sel < 0) {\n'
  '    g.unsup("drawWindow: an icon selection (sel < -1)");\n'
  '    return;\n'
  '  }\n'
  '  const int32_t ex = add32(static_cast<int32_t>(a[0]), 0x1C);\n'
  '  int32_t ey = add32(static_cast<int32_t>(a[1]), 0x2C);\n'
  '  const int32_t H = ctx.gs().g_value587ea0, h = static_cast<int32_t>(a[4]);\n'
  '  const int32_t fx = sub32(ex, control(3) ? 9 : 8), fy = sub32(ey, 8);\n'
  '  const int32_t bx = sub32(ex, 0x32), by = sub32(ey, 0x28);\n'
  '  {\n'
  '    int32_t px = fx, pw = 0x1A0, py = fy, ph = add32(H, 0x10);\n'
  '    round16(px, pw);\n'
  '    round16(py, ph);\n'
  '    gfxs::probe_fill(g, ctx, mode(), px, py, add32(px, pw), add32(py, ph));\n'
  '    gfxs::probe_fill(g, ctx, mode(), bx, by, add32(bx, 0x8C), add32(by, 0x8C));\n'
  '  }\n'
  '  gfxb::draw_frame_r3(g, ctx, fx, fy, 0x1A0, add32(H, 0x10));\n'
  '  const uint32_t root = g.root_va(ctx);\n'
  '  call_body(g, ctx, "Surface_stretchBlit",\n'
  '            {state_va(ctx, &GameState::g_sprites5a53c8) + 0x2C * 29, state_va(ctx, &GameState::g_sprites58b680) + 0x2C * 29,\n'
  '             root, static_cast<uint32_t>(bx), static_cast<uint32_t>(by), 0});\n'
  '  // drawThoughtBubble(sel, bx, by, -1): the head (roadmap S3.5 / S3.6) is held: the probe paints its square\n'
  '  if (mode() >= 0x10000)\n'
  '    gfxs::probe_fill(g, ctx, mode(), bx, by, add32(bx, 0x8C), add32(by, 0x8C));\n'
  '  else\n'
  '    g.unsup("drawThoughtBubble: the head (heads cut and Surface_drawScaled, roadmap S3.6; its palette composeGolferSprite\'s, '
  'S3.5)");\n'
  '  ey = add32(ey, 0x10);\n'
  '  if (h < 0x60 && !control(4)) {\n'
  '    const int32_t d = sub32(sub32(H, h), 0x10);\n'
  '    ey = add32(ey, d / 2);   // (d - (d >> 31)) >> 1: truncated toward zero\n'
  '  }\n'
  '  call_body(g, ctx, "setDrawTarget", {root, state_va(ctx, &GameState::g_font51b360), 0, 0, 0});\n'
  '  gfxb::draw_message_buffer(g, ctx, 0x63, add32(ex, 0x64), control(2) ? add32(ey, 1) : ey, 0x80007FFFu);\n'
  '}\n'
  '\n',
